#ifndef BURNOUT_WIN32_API_TABLE_H
#define BURNOUT_WIN32_API_TABLE_H
#include <stdint.h>

/* Static Win32 import dispatch manifest for the recovered BurnoutPR.exe and
 * dbdata.dll.
 *
 * Generated by port/build/agents/a4-final-census.py from the hash-locked
 * import directories; see (development evidence, not published)
 *
 * Every entry names one DLL!Function pair. `invoke` is the C bridge that
 * implements it, or NULL when no bridge is compiled in / none exists yet.
 * NULL is never a success path: guest_api_dispatch() then calls
 * guest_api_unimplemented(), which logs the exact DLL!Function and stops.
 * `which` selects the operation variant of a shared adapter (see the
 * run_* functions in runtime/startup_host.c).
 *
 * `implementation` is the census status at generation time:
 *   A4_IMPL_C_RUNTIME    adapter exists and is compiled in when its feature
 *                        macro is defined
 *   A4_IMPL_C_CORE_ONLY  C component exists, no adapter yet (always a stop)
 *   A4_IMPL_PYTHON_MODEL only modelled in tools/guest_*.py (always a stop)
 *   A4_IMPL_MISSING      nothing exists (always a stop)
 *
 * `dynamic` marks APIs resolved through GetProcAddress instead of the
 * static import directory.
 */

/* Returned by the named trap. Negative, so it can never be mistaken for a
 * Win32 BOOL/HANDLE/error success value. */
#define A4_TRAP_STOPPED (-4096)

typedef enum {
    A4_SUB_LOADER,
    A4_SUB_KERNEL,
    A4_SUB_HEAP,
    A4_SUB_FILE,
    A4_SUB_THREAD,
    A4_SUB_SYNC,
    A4_SUB_TLS,
    A4_SUB_PROCESS,
    A4_SUB_REGISTRY,
    A4_SUB_WINSOCK,
    A4_SUB_TIME,
    A4_SUB_LOCALE,
    A4_SUB_ENVIRONMENT,
    A4_SUB_ERROR,
    A4_SUB_DEBUG,
    A4_SUB_STRING,
    A4_SUB_CRT,
    A4_SUB_CPP_RUNTIME,
    A4_SUB_USER32,
    A4_SUB_GDI32,
    A4_SUB_D3D11,
    A4_SUB_DXGI,
    A4_SUB_D3DCOMPILER,
    A4_SUB_DINPUT,
    A4_SUB_DBGHELP,
    A4_SUB_IMM32,
    A4_SUB_POWRPROF,
    A4_SUB_OLE,
    A4_SUB_SHELL,
    A4_SUB_WINMM,
    A4_SUB_CRYPTO,
    A4_SUB_UNKNOWN,
    A4_SUB_COUNT
} A4Subsystem;

typedef enum {
    A4_IMPL_UNKNOWN = 0,
    A4_IMPL_C_RUNTIME,
    A4_IMPL_C_CORE_ONLY,
    A4_IMPL_PYTHON_MODEL,
    A4_IMPL_MISSING
} A4Implementation;

/* Uniform bridge signature: `which` selects the adapter variant, `out`
 * receives the 9-word guest CPU state (GPR/EIP/EFLAGS), exactly like the
 * run_* adapters in runtime/startup_host.c. */
typedef int (*GuestApiInvoke)(uint32_t which, uint32_t *out);

typedef struct {
    const char *dll;
    const char *name;
    uint16_t subsystem;
    uint8_t implementation;
    uint8_t which;
    uint8_t dynamic;
    GuestApiInvoke invoke;   /* NULL => named stop */
} GuestApiEntry;

extern const GuestApiEntry guest_api_table[];
extern const uint32_t guest_api_table_count;

/* Named stop: logs "GUEST_API_UNIMPLEMENTED dll!name" and terminates.
 * Returns A4_TRAP_STOPPED only when a test stop handler is installed; it
 * never returns a Win32 success value. */
int guest_api_unimplemented(const char *dll, const char *name);

/* Test/diagnostic hook. A handler that returns turns the stop into
 * A4_TRAP_STOPPED instead of terminating the host process. */
void guest_api_set_stop_handler(void (*handler)(const char *dll, const char *name));

/* Dispatch table entry `index` with its own `which` variant. */
int guest_api_dispatch(uint32_t index, uint32_t *out);
/* Dispatch by DLL!Function name (case-insensitive DLL, exact name). */
int guest_api_dispatch_named(const char *dll, const char *name, uint32_t *out);
/* Lookup helper; NULL when the pair is not a declared import of either module. */
const GuestApiEntry *guest_api_lookup(const char *dll, const char *name);
/* Entries with a given A4Implementation status. */
uint32_t guest_api_count_by_implementation(uint32_t implementation);
/* Entries whose invoke pointer is non-NULL in this build. */
uint32_t guest_api_bound_count(void);

#endif
